`timescale 10ps/10ps
module IKA32010_tb;

reg             EMUCLK = 1'b1;
reg             RS_n = 1'b1;
reg             INT_n = 1'b1;

always #1 EMUCLK = ~EMUCLK;

reg     [1:0]   divider = 2'd0;
always @(posedge EMUCLK) divider <= divider + 2'd1;
wire            cen_n = ~(divider == 2'd3);
wire            refclk = ~divider[1];

initial begin
    #30 RS_n <= 1'b0;
    #100 RS_n <= 1'b1;

    #200 RS_n <= 1'b0;
    #120 RS_n <= 1'b1;

    #2420 INT_n <= 1'b0;
    #63 INT_n <= 1'b1;
end

wire            MEN_n, DEN_n, WE_n;
wire    [11:0]  ADDR;
wire    [15:0]  RDBUS, WRBUS;

IKA32010 main (
    .i_EMUCLK               (EMUCLK                     ),
    .i_CLKIN_PCEN           (~cen_n                     ),

    .o_CLKOUT               (                           ),
    .o_CLKOUT_PCEN          (                           ),
    .o_CLKOUT_NCEN          (                           ),

    .i_RS_n                 (RS_n                       ),

    .o_MEN_n                (MEN_n                      ),
    .o_DEN_n                (DEN_n                      ),
    .o_WE_n                 (WE_n                       ),

    .o_AOUT                 (ADDR                       ),
    .i_DIN                  (RDBUS                      ),
    .o_DOUT                 (WRBUS                      ),
    .o_DOUT_OE              (                           ),

    .i_BIO_n                (1'b1                       ),
    .i_INT_n                (INT_n                      )
);



reg     [15:0]  addrlatch;
always @(posedge EMUCLK) if(!WE_n && ADDR[2:0] == 3'd0) addrlatch <= WRBUS;


reg     [7:0]   m68kram_buf[0:16383];
reg     [15:0]  m68kram[0:8191];
integer i;
initial begin
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/68k.txt", m68kram_buf);

    for(i=0; i<8192; i=i+1) begin
        m68kram[i] = {m68kram_buf[2*i], m68kram_buf[2*i+1]};
    end
end



assign  RDBUS = (DEN_n) ? 16'hZZZZ : m68kram[addrlatch[12:0]];





reg     [7:0]   dsp_hi[0:2047];
reg     [7:0]   dsp_lo[0:2047];
assign  RDBUS = (MEN_n) ? 16'hZZZZ : {dsp_hi[ADDR], dsp_lo[ADDR]};
initial begin
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/dsp_hi.txt", dsp_hi);
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/dsp_lo.txt", dsp_lo);
end








endmodule

//
//  BRANCH INSTRUCTIONS
//

//B - Branch unconditionally
16'b1111_1001_0000_0000: begin
    if(ex_inst_cycle == 2'd0) begin
        busctrl_req = DATA_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;
        if_pc_modesel = PC_LOAD_IMMEDIATE; //deny interrupt request
        ex_inst_cycle_rst = NO;

        //deny interrupt request
        if_opcodereg_force_iack = NO; 
        stk_push = NO; stk_data_sel = STACK_DATA_ACC;
    end
    else if(ex_inst_cycle == 2'd1) begin
        busctrl_req = OPCODE_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;
    end

    `ifdef IKA32010_DISASSEMBLY 
        disasm_type4("B", if_pc, ex_inst_cycle, busctrl_inlatch, 0);
    `endif
end

//BANZ - Branch on auxillary register not zero
16'b1111_0100_0000_0000: begin
    if(ex_inst_cycle == 2'd0) begin
        busctrl_req = DATA_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;
        //deny interrupt request,
        //See User Guide p3-16 (pdf p65) for the AR bits that are evaluated
        if_pc_modesel = (reg_ar[reg_arp][8:0] != 9'h000) ? PC_LOAD_IMMEDIATE : PC_INCREASE; 
        ex_inst_cycle_rst = NO;

        reg_ar_dec = YES; 

        //deny interrupt request
        if_opcodereg_force_iack = NO; 
        stk_push = NO; stk_data_sel = STACK_DATA_ACC;
    end
    else if(ex_inst_cycle == 2'd1) begin
        busctrl_req = OPCODE_READ; busctrl_addr_muxsel = BUSCTRL_ADDR_PC;
    end

    `ifdef IKA32010_DISASSEMBLY
